 u,joint,fixed=truths();cal=np.load(L/'calibration_200k.npz',allow_pickle=True);assert np.array_equal(cal['m1_edges'],[1,1.5,2,2.5,3,4,5]);assert np.allclose(cal['q_edges'],np.arange(.1,1.01,.1));assert np.allclose(Q,np.tile((cal['q_edges'][:-1]+cal['q_edges'][1:])/2,6))
 eps=R[:,:-1].sum(1);eta=u@eps;selected=u*eps/eta;A=R[:,:-1]/eps[:,None];assert np.max(abs(selected@A-project(u)))<1e-14
